-- rate-limit/hit
-- Adds one to a flood-limit counter and returns the new count (lib/net/rate-limit.ts).
-- One row per key and window; concurrent requests are counted correctly.
--
-- Parameters, with the example values used to render this file:
--   $1 = "report:ip:hour:0f3a…"
--   $2 = "2026-11-13T09:00:00.000Z"
--   $3 = 1
--
-- Generated by `pnpm db:queries` from lib/db/queries/rate-limit.ts. Do not edit by hand.

insert into "rate_limits" ("key", "window_start", "count")
values ($1, $2, $3)
on conflict ("key","window_start")
do update
set "count" = "rate_limits"."count" + 1
returning "count";
